package glitch

import data.glitch_lib

# Check if a string contains "root@" (indicating SSH as root)
is_root_ssh(value) {
    value.ir_type == "String"
    regex.match(".*root@.*", value.value)
}

# Helper to recursively check complex values (Sum/Array/Hash) for root SSH pattern
check_value_for_root_ssh(value) {
    value.ir_type == "String"
    is_root_ssh(value)
} else {
    value.ir_type == "Sum"
    check_value_for_root_ssh(value.left)
} else {
    value.ir_type == "Sum"
    check_value_for_root_ssh(value.right)
} else {
    value.ir_type == "Array"
    check_value_for_root_ssh(value.value[_])
} else {
    value.ir_type == "Hash"
    check_value_for_root_ssh(value.value[_].key)
} else {
    value.ir_type == "Hash"
    check_value_for_root_ssh(value.value[_].value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Detect SSH execution as root in command attributes (Puppet/Chef/Ansible shell)
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == "command"
    check_value_for_root_ssh(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Command executed via SSH as root. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Detect remote_user set to root in Ansible playbooks (Playbook-level attribute)
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    attr.name == "remote_user"
    attr.value.ir_type == "String"
    regex.match("(?i)^root$", attr.value.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Playbook connecting as root user. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Detect user set to root in task definitions (Ansible/Chef/Puppet)
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == "user"
    attr.value.ir_type == "String"
    regex.match("(?i)^root$", attr.value.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Task running with root user. (CWE-250)"
    }
}
